import { Folder } from "lucide-react";
import { SettingsPanel } from "./SettingsPanel";
import styles from "./settings.module.css";
export function YourData() {
  return (
    <SettingsPanel
      id="data"
      title="Your data"
      icon={Folder}
      description="Download your profile, preferences, contacts, templates, message history, and attachment metadata. Download your current PDF separately from the PDF attachment section."
    >
      <a
        href="/api/account/export"
        className={`${styles.secondary} secondary-button inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer button-interaction [border:1px_solid_var(--settings-strong)] text-[var(--settings-text)] [background:transparent] shadow-[var(--appearance-shadow,_none)]`}
      >
        ⬇ Download my data
      </a>
      <p
        className={`text-[var(--settings-muted)] text-[14px] leading-[1.65] mt-5`}
      >
        <a
          className={`text-[var(--settings-purple)] font-semibold no-underline wrap-anywhere css-hover:underline inline-flex items-center min-h-11`}
          href="/privacy"
        >
          Privacy Policy
        </a>{" "}
        ·{" "}
        <a
          className={`text-[var(--settings-purple)] font-semibold no-underline wrap-anywhere css-hover:underline inline-flex items-center min-h-11`}
          href="/terms"
        >
          Terms of Service
        </a>
      </p>
    </SettingsPanel>
  );
}
